#!/usr/bin/env node
/**
 * ui-dist-stamp.mjs — the built @kinetixui/ui corresponds to the source under test.
 *
 *   node scripts/ui-dist-stamp.mjs --write   record the stamp (runs at the end of the package build)
 *   node scripts/ui-dist-stamp.mjs           verify it, and say what to run if it is stale
 *
 * ── The hazard this closes ──────────────────────────────────────────────────
 *
 * Storybook is where the browser evidence is measured, and its stories do not all read the same thing:
 *
 *   - 94 of the 97 story files are generated by `scripts/gen-stories.mjs` and import `@kinetixui/ui`,
 *     which the workspace symlink resolves through the package `exports` map to **packages/ui/dist**.
 *   - Button, Input and Textarea are the three hand-written stories that predate the generator, and they
 *     import `../components/…` — **source**.
 *
 * Tailwind, meanwhile, scans source for class names. So in one Storybook build the CSS always describes
 * source while most of the DOM describes whatever was last built, and a measurement taken after editing a
 * component but before rebuilding reads a mixture of the two. That is not theoretical: during the
 * selection-control slice a post-fix measurement came back as 16x16 and 4x4 — numbers belonging to neither
 * version — because the classes had been regenerated and the markup had not.
 *
 * A stale `dist` is worse than a failing check, because it fails *quietly*: the story renders, the
 * measurement succeeds, and the number is about code that is no longer in the repository. Evidence from a
 * stale build is the one kind of evidence this repository must never award.
 *
 * ── Why a content stamp and not a timestamp ─────────────────────────────────
 *
 * mtime would answer a different question. A fresh `git checkout` gives every file the same mtime, a cache
 * restore gives `dist` whatever the cache preserved, and `touch` on a source file would condemn a build
 * that is in fact correct. A hash of the source that tsup bundles answers exactly the question asked: is
 * the artifact in `dist` the artifact this source produces?
 *
 * Note what the stamp does *not* cover, deliberately: tests and stories are excluded, because neither ends
 * up in the bundle — editing a story must not invalidate a build that is still correct.
 *
 * Once the stamp matches, the source/dist split above stops mattering: both are then the same code, so a
 * story that reads the package and a story that reads the file next to it describe one library.
 *
 * The stamp is written into `dist` rather than beside it so that it travels with the build output through
 * turbo's cache (`outputs: ["dist/**"]`) — a restored cache hit must carry its own stamp, or the first
 * check after one would report a staleness that is not real.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const srcDir = join(root, "packages/ui/src");
const distDir = join(root, "packages/ui/dist");
export const STAMP = join(distDir, "kx-src-hash.json");

/** Files tsup reaches from `src/index.ts`, approximated by "everything that is not a test or a story". */
function bundledSources(dir = srcDir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === "stories") continue;
      bundledSources(path, out);
    } else if (/\.tsx?$/.test(entry.name) && !/\.test\.tsx?$/.test(entry.name)) {
      out.push(path);
    }
  }
  return out;
}

/** Path as well as content: moving a component to a new file changes the bundle even if nothing is edited. */
export function sourceHash() {
  const hash = createHash("sha256");
  for (const file of bundledSources()) {
    hash.update(relative(root, file));
    hash.update("\0");
    hash.update(readFileSync(file));
    hash.update("\0");
  }
  return hash.digest("hex");
}

/**
 * Called by the browser evidence scripts before they measure anything. `context` names the caller so the
 * failure says which claim was about to be made against the wrong artifact.
 */
export function assertUiDistMatchesSource(context) {
  if (!existsSync(distDir) || !statSync(distDir).isDirectory()) {
    console.error(`${context}: packages/ui/dist is missing. Run \`pnpm -F @kinetixui/ui build\` first.`);
    process.exit(1);
  }
  if (!existsSync(STAMP)) {
    console.error(
      `${context}: packages/ui/dist carries no source stamp, so it cannot be shown to match the source ` +
        `under test. Run \`pnpm -F @kinetixui/ui build\` to produce one.`,
    );
    process.exit(1);
  }
  const recorded = JSON.parse(readFileSync(STAMP, "utf8")).sourceHash;
  const actual = sourceHash();
  if (recorded !== actual) {
    console.error(
      `${context}: packages/ui/dist was built from different source than the working tree.\n` +
        `  dist was built from  ${recorded.slice(0, 12)}\n` +
        `  the source here is   ${actual.slice(0, 12)}\n` +
        `Most of Storybook's stories import the built package while Tailwind generates its classes from\n` +
        `source, so measuring now would describe a mixture of the two. Run \`pnpm -F @kinetixui/ui build\`\n` +
        `(and rebuild Storybook) before taking this as evidence.`,
    );
    process.exit(1);
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes("--write")) {
    writeFileSync(STAMP, `${JSON.stringify({ sourceHash: sourceHash() }, null, 2)}\n`);
    console.log("ui-dist-stamp — recorded the source hash of this build.");
  } else {
    assertUiDistMatchesSource("ui-dist-stamp");
    console.log("ui-dist-stamp ok — packages/ui/dist was built from the source in the working tree.");
  }
}
